#[inline]
fn destack_crypto_store_probe_kinds_vm_replay(
    binding: &BindingCallContext,
    context: &mut vm::BindingContext<'_>,
    world: RuntimeWorld,
) -> RuntimeResult<vm::Word> {
    let result = binding.trace().run_binding(
        CRYPTO_STORE_PROBE_KINDS,
        binding.replay_payload_for(CRYPTO_STORE_PROBE_KINDS)?,
        context,
        |context| match world {
            RuntimeWorld::Host => platform_vm::destack_crypto_store_probe_kinds(binding, context),
            RuntimeWorld::Simulation => {
                platform_simulation_vm::destack_crypto_store_probe_kinds(binding, context)
            }
        },
        |context, result| {
            let context = &context.read();
            if let Ok(value) = result {
                let result_value: VmArray<CryptoStoreKind> = value.clone();
                let result_recorded_raw = result_value.values(context)?;
                let mut result_recorded = Vec::with_capacity(result_recorded_raw.len());
                for result_recorded_item_value in result_recorded_raw {
                    let result_recorded_item_raw = decode_int32(
                        result_recorded_item_value,
                        "result_recorded_item_raw",
                        "item",
                    )?;
                    let result_recorded_item = match result_recorded_item_raw {
                        0i32 => CryptoStoreKind::System,
                        1i32 => CryptoStoreKind::User,
                        2i32 => CryptoStoreKind::Machine,
                        3i32 => CryptoStoreKind::Provider,
                        4i32 => CryptoStoreKind::Ephemeral,
                        _ => {
                            return Err(RuntimeError::from(PlatformError::invalid_argument_value(
                                "result_recorded_item",
                                "unknown CryptoStoreKind value",
                            ))
                            .boxed());
                        }
                    };
                    let result_recorded_item_recorded = result_recorded_item;
                    result_recorded.push(result_recorded_item_recorded);
                }
                let payload = CryptoStoreProbeKindsReplayRecord {
                    result: Ok(result_recorded),
                };
                return Ok(Some(payload));
            }

            if let Err(error) = result {
                let payload = {
                    let result = Err(TraceError::from(error.as_ref()));
                    CryptoStoreProbeKindsReplayRecord { result }
                };
                return Ok(Some(payload));
            }

            Ok(None)
        },
        |context, payload| {
            let context = &mut context.write();
            // replay result
            match payload.result {
                Ok(value) => {
                    let mut vm_result_builder =
                        VmArray::<CryptoStoreKind>::builder(context, value.len())?;
                    for vm_result_item in value {
                        let vm_result_item_value = vm_result_item;
                        vm_result_builder.push(context, vm_result_item_value)?;
                    }
                    let vm_result = vm_result_builder.finish()?;
                    Ok(vm_result)
                }
                Err(error) => Err(Box::<RuntimeError>::from(error)),
            }
        },
    );
    let result = encode_destack_crypto_store_probe_kinds_result(context, result)?;
    Ok(result)
}

